import { useEffect, useMemo, useState } from 'react';
import { useLanguage } from '../../../../core/i18n';
import {
  getProyectoParticipantesCache,
  getProyectoParticipantes,
  normalizeProyectoParticipantes,
} from '../services/projectsService';
import ProjectParticipantAvatar from './ProjectParticipantAvatar';

function getProjectId(project = {}) {
  const candidates = [
    project.id_proyecto,
    project.backendId,
    project.idProyecto,
    project.id,
  ];

  for (const value of candidates) {
    if (!value) continue;

    const clean = String(value).trim();
    const syntheticMatch = clean.match(/^proyecto-(.+)$/i);
    return syntheticMatch?.[1] || value;
  }

  return null;
}

function getExpectedCount(project = {}, fallback = 0) {
  const raw =
    project.participantes_count ??
    project.participants_count ??
    project.colaboradores_count ??
    project.collaborators_count;
  const count = Number(raw);

  return Number.isFinite(count) && count > 0 ? count : fallback;
}

function normalizeText(value = '') {
  return String(value || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function isTruthy(value) {
  if (value === true || value === 1) return true;
  if (value === false || value === 0 || value === null || value === undefined) return false;

  if (typeof value === 'string') {
    const normalized = normalizeText(value);
    return [
      '1',
      'true',
      'si',
      'validado',
      'validated',
      'verificado',
      'verified',
      'aprobado',
      'approved',
      'github_validado',
    ].includes(normalized);
  }

  if (typeof value === 'object') {
    return Object.keys(value).length > 0;
  }

  return Boolean(value);
}

function isValidatedParticipant(participante = {}) {
  const tipo = normalizeText(participante.tipo_participante || participante.tipoParticipante || '');

  return tipo === 'usuario_github_validado'
    || tipo === 'github_validado'
    || tipo === 'validado'
    || isTruthy(participante.validacion_github)
    || isTruthy(participante.validacionGithub)
    || isTruthy(participante.github_validado)
    || isTruthy(participante.githubValidated)
    || isTruthy(participante.validacion?.validado)
    || isTruthy(participante.validacion?.estado)
    || isTruthy(participante.estado_validacion)
    || isTruthy(participante.estadoValidacion)
    || isTruthy(participante.github_validation_status)
    || isTruthy(participante.usuario_repositorio_validacion);
}

function participantKey(participante = {}) {
  const userId = participante.id_usuario || participante.idUsuario;
  if (userId) return `usuario:${userId}`;

  const githubId = participante.github_id || participante.githubId;
  if (githubId) return `github-id:${githubId}`;

  const github = participante.github_username || participante.login;
  if (github) return `github:${normalizeText(github)}`;

  const email = participante.email || participante.correo;
  if (email) return `email:${normalizeText(email)}`;

  const avatar = participante.avatar_url || participante.avatarUrl;
  if (avatar) return `avatar:${String(avatar).split('?')[0].toLowerCase()}`;

  const id = participante.id || participante.id_participacion;
  if (id) return `id:${id}`;

  return `nombre:${normalizeText(participante.nombre)}`;
}

function mergeParticipants(...groups) {
  const map = new Map();

  groups.flat().forEach((participante) => {
    if (!participante) return;

    const key = participantKey(participante);
    const current = map.get(key);

    map.set(key, {
      ...current,
      ...participante,
      nombre: current?.nombre || participante.nombre || participante.github_username || participante.__defaultName || 'Participante',
      avatar_url: current?.avatar_url || participante.avatar_url || '',
      github_username: current?.github_username || participante.github_username || '',
      email: current?.email || participante.email || participante.correo || '',
      repositorios: [
        ...(current?.repositorios || []),
        ...(participante.repositorios || []),
      ].filter(Boolean),
    });
  });

  return Array.from(map.values()).sort((a, b) => {
    if (a.tipo_rol === b.tipo_rol) {
      return (a.nombre || '').localeCompare(b.nombre || '');
    }

    if (a.tipo_rol === 'owner') return -1;
    if (b.tipo_rol === 'owner') return 1;
    return 0;
  });
}

const PARTICIPANT_GROUPS = [
  {
    key: 'usuario_github_validado',
    labelKey: 'projects.github.validated',
    match: (participante) => participante.tipo_participante === 'usuario_github_validado'
      || (participante.tiene_cuenta && participante.validacion_github),
  },
  {
    key: 'usuario_sin_validacion_github',
    labelKey: 'projects.participation.unvalidated',
    match: (participante) => participante.tipo_participante === 'usuario_sin_validacion_github'
      || (participante.id_usuario && !participante.validacion_github),
  },
];

function groupParticipants(participantes = []) {
  const assigned = new Set();

  const groups = PARTICIPANT_GROUPS.map((group) => {
    const items = participantes.filter((participante, index) => {
      if (assigned.has(index) || !group.match(participante)) return false;
      assigned.add(index);
      return true;
    });

    return { ...group, items };
  }).filter(group => group.items.length > 0);

  const unassigned = participantes.filter((_, index) => !assigned.has(index));

  if (unassigned.length > 0) {
    const sinValidacion = groups.find(group => group.key === 'usuario_sin_validacion_github');

    if (sinValidacion) {
      sinValidacion.items = [...sinValidacion.items, ...unassigned];
    } else {
      groups.push({
        key: 'usuario_sin_validacion_github',
        labelKey: 'projects.participation.unvalidated',
        items: unassigned,
      });
    }
  }

  return groups;
}

function ParticipantsList({ participantes = [] }) {
  if (participantes.length === 0) return null;

  return (
    <div className="prj-collab-avatar-stack">
      {participantes.map((participante, index) => (
        <ProjectParticipantAvatar
          key={`${participante.id || participante.id_usuario || participante.github_username || index}`}
          participante={participante}
        />
      ))}
    </div>
  );
}

function ParticipantGroup({ label, labelKey, participantes = [] }) {
  if (participantes.length === 0) return null;

  return (
    <div className="prj-collab-row">
      <div className="prj-collab-label">
        <span>{labelKey ? label : label}</span>
        <span>{participantes.length}</span>
      </div>
      <ParticipantsList participantes={participantes} />
    </div>
  );
}

export default function ProjectsGithubCollaborators({
  proyecto = {},
  detail = false,
  fetchRemote = true,
  fallbackToCurrentUser = true,
  validatedOnly = false,
  compact = false,
}) {
  const { t } = useLanguage();
  const directParticipants = useMemo(
    () => normalizeProyectoParticipantes(proyecto, { includeCurrentUserFallback: false }),
    [proyecto]
  );
  const initialParticipants = useMemo(
    () => directParticipants.length > 0
      ? directParticipants
      : normalizeProyectoParticipantes(proyecto, { includeCurrentUserFallback: fallbackToCurrentUser }),
    [directParticipants, proyecto, fallbackToCurrentUser]
  );
  const [participantes, setParticipantes] = useState(initialParticipants);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const projectId = getProjectId(proyecto);
    const shouldFetchBackend = Boolean(projectId) && fetchRemote;

    setParticipantes(initialParticipants);

    if (!shouldFetchBackend) {
      setLoading(false);
      return undefined;
    }

    let isActive = true;
    const cachedParticipants = getProyectoParticipantesCache(projectId);

    if (cachedParticipants.length > 0) {
      setParticipantes(cachedParticipants);
      setLoading(false);
    } else {
      setLoading(true);
    }

    const requests = [
      getProyectoParticipantes(projectId).catch(() => []),
    ];

    Promise.all(requests)
      .then(([platformItems]) => {
        if (!isActive) return;
        const baseParticipants = platformItems.length > 0
          ? []
          : (cachedParticipants.length > 0 ? cachedParticipants : initialParticipants);
        const merged = mergeParticipants(baseParticipants, platformItems);
        setParticipantes(merged.length > 0 ? merged : baseParticipants);
      })
      .finally(() => {
        if (!isActive) return;
        setLoading(false);
      });

    return () => {
      isActive = false;
    };
  }, [proyecto, initialParticipants, directParticipants.length, fetchRemote]);

  useEffect(() => {
    const projectId = getProjectId(proyecto);
    if (!projectId || !fetchRemote) return undefined;

    let isActive = true;

    const handleParticipantsChanged = (event) => {
      const changedProjectId = event?.detail?.id;
      if (changedProjectId && String(changedProjectId) !== String(projectId)) return;

      setLoading(true);

      getProyectoParticipantes(projectId)
        .then((items) => {
          if (!isActive) return;
          const baseParticipants = items.length > 0 ? [] : initialParticipants;
          const merged = mergeParticipants(baseParticipants, items);
          setParticipantes(merged.length > 0 ? merged : baseParticipants);
        })
        .finally(() => {
          if (!isActive) return;
          setLoading(false);
        });
    };

    window.addEventListener('projects:participants-changed', handleParticipantsChanged);

    return () => {
      isActive = false;
      window.removeEventListener('projects:participants-changed', handleParticipantsChanged);
    };
  }, [proyecto, initialParticipants, fetchRemote]);

  const visibles = participantes.length > 0 ? participantes : initialParticipants;
  const displayParticipants = useMemo(
    () => validatedOnly
      ? visibles.filter(isValidatedParticipant)
      : visibles,
    [visibles, validatedOnly]
  );
  const groupedParticipants = useMemo(
    () => groupParticipants(displayParticipants),
    [displayParticipants]
  );
  const counter = compact || validatedOnly
    ? displayParticipants.length
    : Math.max(getExpectedCount(proyecto, displayParticipants.length), displayParticipants.length);

  if (displayParticipants.length === 0 && !loading) {
    return null;
  }

  return (
    <div className={`prj-collaborators${detail ? ' detail' : ''}${compact ? ' compact' : ''}`} aria-busy={loading}>
      <div className="prj-collab-head">
        <span>{t('projects.config.participants')}</span>
        <span>{counter}</span>
      </div>

      {compact ? (
        <div className="prj-collab-compact-row">
          <ParticipantsList participantes={displayParticipants} />
          {loading && displayParticipants.length === 0 && (
            <div className="prj-collab-loading">
              <span />
              <span />
              <span />
            </div>
          )}
        </div>
      ) : (
        <div className="prj-collab-groups">
          {groupedParticipants.map((group) => (
            <ParticipantGroup
              key={group.key}
              label={group.labelKey ? t(group.labelKey) : group.label}
              participantes={group.items}
            />
          ))}

          {loading && displayParticipants.length === 0 && (
            <div className="prj-collab-loading">
              <span />
              <span />
              <span />
            </div>
          )}
        </div>
      )}

    </div>
  );
}
